CREATE FUNCTION cmd_reject_survival_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Survival task receipts are immutable'; END $$;
CREATE TRIGGER cmd_survival_task_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_survival_task_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_survival_mutation();
CREATE FUNCTION cmd_validate_survival_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE task cmd_actor_task_receipt%ROWTYPE; required boolean; BEGIN SELECT availability_required INTO STRICT required FROM rule_survival_operation WHERE rule_id=NEW.operation_rule_id AND operation_code=NEW.operation_code; IF NOT required AND NOT NEW.opportunity_available THEN RAISE EXCEPTION 'Availability applies only to gated Survival operations'; END IF; IF NEW.task_command_id IS NOT NULL THEN SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; IF task.actor_id<>NEW.actor_id OR task.skill_rule_id<>(SELECT skill_rule_id FROM rule_survival_mechanic WHERE rule_id=NEW.operation_rule_id) OR task.check_total<>NEW.check_total OR task.effect<>NEW.effect OR task.succeeded<>NEW.succeeded THEN RAISE EXCEPTION 'Survival receipt does not match its task'; END IF; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_survival_task_receipt_valid AFTER INSERT ON cmd_survival_task_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_survival_receipt();
